// "API 等价" on 设置 · 额度 (PRD F11): what a model's tokens would cost at the provider's API prices. Not what a plan
// subscriber pays. Prices come from LiteLLM's table (model-prices.data.ts, generated by scripts/update-model-prices.mjs).
import { MODEL_PRICES } from './model-prices.data'
import type { TokenSplit } from './usage-stats'

type Price = (typeof MODEL_PRICES)[string]

/** The price for a model id as the agents log it: exact, then without a `[…]` option suffix or a `-YYYYMMDD` date. */
export function priceOf(model: string): Price | null {
  const bare = model.replace(/\[.*\]$/, '').trim()
  return MODEL_PRICES[bare] ?? MODEL_PRICES[bare.replace(/-\d{8}$/, '')] ?? null
}

/** USD for these tokens at API prices, or null when the model has no known price. Unpriced cache tokens cost as input. */
export function apiCost(model: string, t: TokenSplit): number | null {
  const p = priceOf(model)
  if (!p) return null
  return (t.input * p.input + t.output * p.output + t.cacheRead * (p.cacheRead ?? p.input) + t.cacheWrite * (p.cacheWrite ?? p.input)) / 1e6
}
